/**
 * Tax withheld on one month's gross, per the table. Skatteverket publishes an
 * amount per income bracket rather than a rate, and the rate it works out to
 * climbs with the month â€” which is why no one can simply state their
 * percentage. Gross is truncated to whole kronor, as the tables are indexed.
 */
export function taxFromTable(gross: number, table: number): number | null {
  const t = TABLES[table];
  if (!t || gross <= 0) return null;
  const target = Math.floor(gross);

  let lo = 0;
  let hi = t.from.length - 1;
  if (target < t.from[0]) return 0;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (t.from[mid] <= target) lo = mid;
    else hi = mid - 1;
  }
  return t.tax[lo];
}
